    tweakDescs: {
      'tcp-keepalive': 'Sets KeepAliveTime=30s (from 2h) and KeepAliveInterval=1s. Drops stale connections faster — reduces ghost connections in multiplayer games.',
      'dns-doh': 'Routes DNS queries over encrypted HTTPS instead of plain UDP. Prevents ISP DNS snooping. Applies Cloudflare DoH (1.1.1.1) via Windows 11 native DoH setting.',
      'disable-autoproxy': 'Stops Windows from auto-detecting proxy settings on every connection. Eliminates a source of connection delay and DNS-level latency spikes.',
      'nic-ndis-poll': 'Replaces interrupt-driven packet delivery with polling — cuts worst-case DPC latency from ~500µs to ~50µs on supported NICs (Intel I225/I226, Realtek 8125). The same technique used in professional gaming infrastructure.',
      'nic-rss-affinity': 'Pins RSS queue processing to dedicated CPU cores away from core 0, where OS timer interrupts land. Prevents NIC DPC handling from preempting your game thread. Measurable benefit on 6+ core CPUs.',
      'disable-mpo': 'Sets OverlayTestMode=5 in DWM registry — forces Windows to stop using GPU overlay planes for compositing. Eliminates a class of GPU driver-level flicker, black screen, and frame-time variance bugs present on NVIDIA and AMD. Documented fix by both GPU vendors. Reboot required.',
      'disable-paging-executive': 'Sets DisablePagingExecutive=1 — prevents the Windows kernel, HAL, and driver code from being paged out to disk. Eliminates the random multi-millisecond stall that occurs when a paged-out driver gets called on a game thread. Most impactful on systems with active paging pressure (16GB RAM, many background processes).',
      'large-system-cache': 'Ensures LargeSystemCache=0 — tells the kernel memory manager to optimise RAM for application working sets rather than the file system cache. On open-world games with heavy asset streaming this prevents the FS cache from stealing RAM from the game\'s texture/geometry working set.',
      'split-large-caches': 'Sets SplitLargeCaches=1 — enables the Windows scheduler to be aware of CPU L3 cache topology when placing threads. Threads are scheduled onto cores sharing the same L3 cache segment, reducing cross-CCX cache-miss latency. Most impactful on AMD Ryzen CPUs with multiple cache complexes (Zen 2/3/4).',
      'tcp-timedwait': 'Sets TcpTimedWaitDelay=30 (default: 240 seconds). Speeds up port reuse after connections close — critical for game servers with frequent reconnects. Reduces TIME_WAIT socket accumulation that can cause port exhaustion on high-activity multiplayer sessions.',
      'net-del-ack': 'Sets TcpDelAckTicks=0 (default: 2). Sends ACKs immediately instead of batching them every ~200ms. Reduces round-trip latency for real-time game protocols where every millisecond of ACK delay directly increases perceived ping.',
      'net-max-ports': 'Expands the ephemeral TCP port range from the Windows default of ~16,384 ports to 64,510 using netsh. Prevents port exhaustion on game servers with high connection turnover — required for high-concurrency FiveM, Rust, and MMO servers.',
      // CS2
      'cs2-network': 'Disables Nagle algorithm and sets TcpAckFrequency=1. Every game packet is sent immediately — no buffering delay.',
      'cs2-mmcss': 'Sets MMCSS GPU Priority=8, Scheduling Category=High. Forces Windows to treat GPU work as real-time multimedia.',
      'cs2-priority': 'Writes CpuPriorityClass=3 + IoPriority=3 to cs2.exe IFEO. CS2 gets elevated CPU cycles on every launch automatically.',
      'cs2-fullscreen-opti': 'Sets DISABLEDXMAXIMIZEDWINDOWEDMODE for cs2.exe. Forces true exclusive fullscreen, bypassing DWM compositing.',
      'cs2-timer': 'Sets GlobalTimerResolutionRequests=1 for 0.5ms system timer precision. Reduces game-loop interval jitter.',
      'cs2-gpu-prerender': 'Sets NVIDIA PreRenderedFrames=1. Minimises the GPU render-ahead queue to one frame — reduces display latency directly.',
      'cs2-audio-latency': 'Sets Multimedia SystemProfile AlwaysOn=1 + LazyModeTimeout=0. Prevents the audio engine from entering power-save mid-session.',
      'cs2-input-responsiveness': 'Reduces mouclass MouseDataQueueSize to 16 and sets IRQ8Priority=1. Shrinks the OS mouse input buffer for faster event processing.',
      'cs2-affinity': 'Computes CpuAffinityMask from physical P-core count and writes it to cs2.exe IFEO. Prevents CS2 threads from scheduling onto E-cores.',
      'cs2-gpu-scheduling': 'Enables Hardware-Accelerated GPU Scheduling (HAGS) via HwSchMode=2. Moves GPU work scheduling from CPU driver to GPU hardware.',
      'cs2-network-recv-buf': 'Sets AFD socket receive/send buffers to 128 KB. Tightens the Windows socket buffer to match CS2\'s packet cadence.',
      'cs2-hpet-off': 'Disables HPET via bcdedit and enables disabledynamictick. Forces TSC/LAPIC timing for lower DPC latency.',
      'cs2-power-throttle-off': 'Sets PowerThrottlingOff=1. Prevents Windows from applying EcoQoS throttling to foreground apps — CS2 always gets full CPU frequency.',
    },
